// The honest answer for an ask the guide doesn't know: it says
// so, and offers the nearest useful door (the All Features hub)
// plus the topics it does know. Never an invented answer.
export const GUIDE_FALLBACK: GuideEntry = {
  id: 'fallback',
  patterns: [],
  answer:
    'That one\u2019s beyond my guiding \u2014 I can\u2019t guide it yet, and I won\u2019t make something up. Everything in the game lives behind one of these doors, and the All Features hub shows them all. Or ask me about battles, colours, your wallet, moderation, your pins, or who can see you \u2014 those I know cold.',
  action: route('Show me everything', '/features'),
};

// First hit wins; the table is ordered specific -> general.
export function matchGuideIntent(text: string): GuideEntry | null {
  const t = text.trim();
  if (!t) return null;
  for (const entry of GUIDE_ENTRIES) {
    if (entry.patterns.some(p => p.test(t))) return entry;
  }
  return null;
}

// Is this line shaped like an ask (a question or a request), as
// opposed to conversation? Ask-shaped lines that match nothing
// get the honest fallback; plain chatter keeps the scripted
// conversation it has always had.
export function looksLikeAsk(text: string): boolean {
  const t = text.trim();
  if (!t) return false;
  if (t.includes('?')) return true;
  return /^(how|where|what|when|who|why|can|could|do|does|is|are|take|show|open|go|find|tell|help)\b/i.test(
    t
  );
}

// The chips offered above the chat input, in table order.
export const GUIDE_CHIPS: GuideEntry[] = GUIDE_ENTRIES.filter(e => e.chip);
