// Owner loadout (Round 36.9 Part 8, Eddie 2026-11-20: "give me
// bag items so I can use them and make sure they work... load me
// up, make my profile robust").
//
// When Owner Mode is ON (an owner email, or the Profile toggle),
// the bag is seeded ONCE with a working stock of every bag item —
// enough of each to really exercise the flows — plus a demo
// battle-points balance that can exercise the Explorer Bag
// purchase (the upsell is 500; the seed tops the balance up to
// 750).
//
// Rules (Eddie's, exact):
// - Seed exactly ONCE per device (the storage flag below). Using
//   items decrements for real and the stock NEVER silently
//   refills — the flag is never cleared by the app.
// - Top-up semantics: the seed grants only the shortfall, so a
//   stock the owner already earned is never cut down to the seed.
// - Non-owner players are completely unaffected: with Owner Mode
//   off this component does nothing at all.
// - No prices, handlers, or item behaviour change — the seed
//   flows through the same grant paths everything else uses
//   (grantPotions / grantItems / the FightClub points credit).
import React, { useEffect } from 'react';
import { useOwnerMode } from '../utils/ownerMode';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { getPotions, grantPotions, type PotionCounts } from '../utils/potions';
import { getItems, grantItems, type ItemCounts } from '../utils/items';

export const OWNER_LOADOUT_FLAG = 'glacer-owner-loadout-v1';
export const OWNER_LOADOUT_POINTS = 750;
export const OWNER_LOADOUT_POTIONS: PotionCounts = { health: 5, recharge: 5, power: 3 };
export const OWNER_LOADOUT_ITEMS: ItemCounts = { emeralds: 2, shields: 3, crystals: 3 };

const OwnerLoadoutSeeder: React.FC = () => {
  const owner = useOwnerMode();
  const { points, grantPoints } = useNavitarFightClub();

  useEffect(() => {
    if (!owner) return;
    let seeded = false;
    try {
      seeded = localStorage.getItem(OWNER_LOADOUT_FLAG) === '1';
    } catch {
      seeded = false;
    }
    if (seeded) return;
    // Top-up only: grant the shortfall against the seed targets
    // (the grant paths ignore non-positive adds), so a stock the
    // owner already earned is never cut down to the seed.
    const p = getPotions();
    grantPotions({
      health: OWNER_LOADOUT_POTIONS.health - p.health,
      recharge: OWNER_LOADOUT_POTIONS.recharge - p.recharge,
      power: OWNER_LOADOUT_POTIONS.power - p.power,
    });
    const it = getItems();
    grantItems({
      emeralds: OWNER_LOADOUT_ITEMS.emeralds - it.emeralds,
      shields: OWNER_LOADOUT_ITEMS.shields - it.shields,
      crystals: OWNER_LOADOUT_ITEMS.crystals - it.crystals,
    });
    if (points < OWNER_LOADOUT_POINTS) grantPoints(OWNER_LOADOUT_POINTS - points);
    try {
      localStorage.setItem(OWNER_LOADOUT_FLAG, '1');
    } catch {
      // Storage unavailable: the top-up semantics make a repeat
      // pass a no-op anyway (the shortfall is zero once stocked).
    }
  }, [owner, points, grantPoints]);

  return null;
};

export default OwnerLoadoutSeeder;
