// Count-up stat (Modern View prototype): the number rolls up to
// its real value on the expo-out curve when Home mounts. Reduced
// motion (or no rAF) lands on the value instantly. Real data only —
// the values come from the FightClub record, never invented.
function useCountUp(target: number, durationMs = 900): number {
  const [shown, setShown] = useState(0);
  useEffect(() => {
    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      setShown(target);
      return undefined;
    }
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      const k = Math.min(1, (t - t0) / durationMs);
      setShown(Math.round(target * (1 - Math.pow(1 - k, 3))));
      if (k < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, durationMs]);
  return shown;
}

const StatCell: React.FC<{ value: number; label: string }> = ({ value, label }) => {
  const shown = useCountUp(value);
  return (
    <Paper sx={{ p: 2, textAlign: 'center' }}>
      <Typography
        sx={{
          fontSize: '1.55rem',
          fontWeight: 700,
          lineHeight: 1,
          fontVariantNumeric: 'tabular-nums',
        }}
      >
        {shown.toLocaleString()}
      </Typography>
      <Typography
        variant="caption"
        color="text.secondary"
        sx={{ display: 'block', mt: 0.75, fontWeight: 700 }}
      >
        {label}
      </Typography>
    </Paper>
  );
};

// The hero card's XP bar: fills from empty to the navitar's real XP
// fraction once on mount (CSS width transition — no JS re-animation
// of the number itself). Reduced motion snaps straight to the value.
const HeroXpBar: React.FC<{ fraction: number }> = ({ fraction }) => {
  const [w, setW] = useState(0);
  useEffect(() => {
    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      setW(fraction * 100);
      return undefined;
    }
    const raf = requestAnimationFrame(() => setW(fraction * 100));
    return () => cancelAnimationFrame(raf);
  }, [fraction]);
  return (
    <Box
      sx={{
        height: 10,
        borderRadius: 999,
        bgcolor: 'rgba(148, 214, 230, 0.16)',
        overflow: 'hidden',
        mt: 0.75,
      }}
    >
      <Box
        sx={{
          height: '100%',
          width: `${w}%`,
          borderRadius: 999,
          background: 'linear-gradient(90deg, #0b7d9b, #12a5c7)',
          transition: 'width 0.85s cubic-bezier(0.16, 1, 0.3, 1)',
        }}
      />
    </Box>
  );
};

