// Notifications context (Round 17, Eddie 2026-11-17) — the React
// face of the one notifications store (utils/notifications.ts).
//
// Responsibilities:
// - Hold the record list (persisted via the store util on every
//   change) and the unread count the top-bar bell badges.
// - `notify()` is the producers' door: it stores the record AND
//   queues its corner toast. Dedupe by id lives in the store util,
//   so a producer re-firing can never duplicate or re-toast.
// - The toast queue is SESSION state only: a toast pops when news
//   arrives, goes down fast, and never resurrects on reload — the
//   record (and the badge) is what persists. That split is Eddie's
//   brief exactly: pop-up for the moment, a place for afterwards.
// - `activate()` is the tap: mark read, run the record's side
//   effect, land the player where the notification points. Venue
//   records stash the map focus first (the venueBuzz handoff the
//   old pill used); icebreaker records re-open the person's meet
//   card through PresenceContext's meet handoff; friend/suggestion
//   records land on the Friends page where the person lives.
//
// Mounted inside PresenceProvider (it reads the meet handoff) and
// inside the Router (it navigates) — see App.tsx.
import React, { createContext, useCallback, useContext, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { setVenueFocus } from '../data/venueBuzz';
import {
  addNotification,
  loadNotifications,
  saveNotifications,
  type GlacerNotification,
  type NotificationInput,
} from '../utils/notifications';
import { usePresence } from './PresenceContext';

interface NotificationsContextType {
  notifications: GlacerNotification[];
  unreadCount: number;
  // Records currently showing as corner toasts (newest first).
  toasts: GlacerNotification[];
  notify: (input: NotificationInput) => void;
  dismissToast: (id: string) => void;
  markRead: (id: string) => void;
  markAllRead: () => void;
  activate: (notification: GlacerNotification) => void;
}

const NotificationsContext = createContext<NotificationsContextType>({
  notifications: [],
  unreadCount: 0,
  toasts: [],
  notify: () => {},
  dismissToast: () => {},
  markRead: () => {},
  markAllRead: () => {},
  activate: () => {},
});

export const useNotifications = () => useContext(NotificationsContext);

export const NotificationsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const navigate = useNavigate();
  const { meetPerson } = usePresence();
  const [notifications, setNotifications] = useState<GlacerNotification[]>(() =>
    loadNotifications()
  );
  // Ids of records whose corner toast is still up, in arrival
  // order. Session-only by design (see the header comment).
  const [toastIds, setToastIds] = useState<string[]>([]);
  const notificationsRef = useRef(notifications);
  notificationsRef.current = notifications;

  const notify = useCallback((input: NotificationInput) => {
    const { records, added } = addNotification(notificationsRef.current, input);
    if (!added) return;
    notificationsRef.current = records;
    setNotifications(records);
    saveNotifications(records);
    setToastIds(prev => [...prev, input.id]);
  }, []);

  const dismissToast = useCallback((id: string) => {
    setToastIds(prev => prev.filter(t => t !== id));
  }, []);

  const markRead = useCallback((id: string) => {
    setNotifications(prev => {
      if (!prev.some(n => n.id === id && !n.read)) return prev;
      const next = prev.map(n => (n.id === id ? { ...n, read: true } : n));
      notificationsRef.current = next;
      saveNotifications(next);
      return next;
    });
  }, []);

  const markAllRead = useCallback(() => {
    setNotifications(prev => {
      if (!prev.some(n => !n.read)) return prev;
      const next = prev.map(n => (n.read ? n : { ...n, read: true }));
      notificationsRef.current = next;
      saveNotifications(next);
      return next;
    });
  }, []);

  const activate = useCallback(
    (notification: GlacerNotification) => {
      markRead(notification.id);
      dismissToast(notification.id);
      if (notification.kind === 'venue' && notification.venueId) {
        // The old pill's landing: the map selects + flies to the
        // venue (RealmMap consumes the focus on mount).
        setVenueFocus(notification.venueId);
        navigate('/map');
        return;
      }
      if (notification.kind === 'icebreaker' && notification.venueId && notification.personId) {
        // Re-open that person's meet card on the map — from there
        // the intro (and its ⚔️ Battle answer) runs as always.
        meetPerson(notification.venueId, notification.personId);
        return;
      }
      navigate(notification.route);
    },
    [dismissToast, markRead, meetPerson, navigate]
  );

  const value = useMemo<NotificationsContextType>(() => {
    const byId = new Map(notifications.map(n => [n.id, n]));
    return {
      notifications,
      unreadCount: notifications.filter(n => !n.read).length,
      toasts: toastIds
        .map(id => byId.get(id))
        .filter((n): n is GlacerNotification => !!n)
        .reverse(),
      notify,
      dismissToast,
      markRead,
      markAllRead,
      activate,
    };
  }, [notifications, toastIds, notify, dismissToast, markRead, markAllRead, activate]);

  return <NotificationsContext.Provider value={value}>{children}</NotificationsContext.Provider>;
};
