import React, { useCallback, useEffect, useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Chip,
  Button,
  Switch,
  FormControlLabel,
  LinearProgress,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { useNavitar } from '../contexts/NavitarContext';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { useVenue } from '../contexts/VenueContext';
import { usePresence } from '../contexts/PresenceContext';
import { useUser } from '../contexts/UserContext';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../utils/supabaseClient';
import { OWNER_FLAG_KEY, isOwnerEmail, setOwnerFlag, useOwnerMode } from '../utils/ownerMode';
import { mergeLocalProfileWithAccount } from '../utils/accountMerge';
