import { UsernameClaimCard } from '../components/UsernameClaim';
import {
  acceptFriendRequest,
  blockPlayer,
  declineFriendRequest,
  fetchAcceptedFriends,
  fetchAcceptedIncomingChallenges,
  fetchBlockedProfiles,
  fetchIncomingChallenges,
  fetchIncomingRequests,
  fetchSentChallenges,
  navitarSnapshot,
  searchProfilesByUsername,
  sendChallenge,
  sendFriendRequest,
  startFriendDuel,
  unblockPlayer,
  type ChallengeEntry,
  type FriendEntry,
  type ProfileRow,
} from '../utils/onlineFriends';
import {
  ALL_NAVITAR_LOOKS,
  elementColor,
  elementEmoji,
  resolveNavitarArt,
} from '../utils/navitarArt';
