import React, { useState } from 'react';
import { Box, Button, Paper, TextField, Typography } from '@mui/material';
import { useAuth } from '../contexts/AuthContext';

// Set-new-password form for the password-reset landing. Rendered
// app-wide (App.tsx, above the routed page) whenever AuthContext is
// in recovery mode — i.e. the app was opened from a Supabase reset
// email link. The reset link's redirect target is the app root, so
// the form cannot live on the Profile page alone; it sits above
// whatever page the link landed on, in the same Paper/TextField/
// Button family as the Profile account card. On success the
// recovery session simply continues as a normal signed-in session.
const PasswordRecovery: React.FC = () => {
  const { recoveryMode, updatePassword, dismissRecovery, user } = useAuth();
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);

  if (!recoveryMode) return null;

  const handleSubmit = async () => {
    setError(null);
    if (password.length < 6) {
      setError('Use at least 6 characters for the new password.');
      return;
    }
    if (password !== confirm) {
      setError('Those passwords do not match — type the same one twice.');
      return;
    }
    setBusy(true);
    const err = await updatePassword(password);
    setBusy(false);
    if (err) {
      setError(err);
      return;
    }
    setDone(true);
  };

  return (
    <Box sx={{ maxWidth: 640, mx: 'auto', mt: 2, px: 2 }}>
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>
          Set a new password
        </Typography>
        {done ? (
          <>
            <Typography variant="body2" paragraph>
              Password updated — you are signed in
              {user?.email ? ` as ${user.email}` : ''} with your new password.
            </Typography>
            <Button variant="contained" size="small" onClick={dismissRecovery}>
              Continue
            </Button>
          </>
        ) : (
          <>
            <Typography variant="body2" color="text.secondary" paragraph>
              You followed a password reset link{user?.email ? ` for ${user.email}` : ''}. Choose a
              new password to finish signing in.
            </Typography>
            <TextField
              fullWidth
              margin="dense"
              label="New password"
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              autoComplete="new-password"
            />
            <TextField
              fullWidth
              margin="dense"
              label="Confirm new password"
              type="password"
              value={confirm}
              onChange={e => setConfirm(e.target.value)}
              autoComplete="new-password"
            />
            <Box sx={{ mt: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              <Button
                variant="contained"
                size="small"
                disabled={busy || !password || !confirm}
                onClick={() => void handleSubmit()}
              >
                Update password
              </Button>
              <Button variant="text" size="small" disabled={busy} onClick={dismissRecovery}>
                Skip for now
              </Button>
            </Box>
            {error && (
              <Typography variant="body2" color="error" sx={{ mt: 1 }}>
                {error}
              </Typography>
            )}
          </>
        )}
      </Paper>
    </Box>
  );
};

export default PasswordRecovery;
