// USERNAME CLAIM CARD (P2.0b) — the one-time claim screen. A signed-in
// account whose profile row has no username yet gets this card on
// Profile: pick a @name, watch the live availability check, claim it.
// A claimed name LOCKS to the account permanently in v1 — the card
// says so up front, before the claim, in plain words; after the claim
// Profile shows the @name as locked and no edit is offered anywhere.
import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, TextField, Typography } from '@mui/material';
import {
  claimUsername,
  isUsernameAvailable,
  isValidUsername,
  normalizeUsername,
  usernameFormatError,
} from '../utils/username';

type CheckState =
  | { kind: 'idle' }
  | { kind: 'checking' }
  | { kind: 'available' }
  | { kind: 'taken' }
  | { kind: 'unverifiable' };

interface UsernameClaimCardProps {
  userId: string;
  onClaimed: (username: string) => void;
}

export const UsernameClaimCard: React.FC<UsernameClaimCardProps> = ({ userId, onClaimed }) => {
  const [input, setInput] = useState('');
  const [check, setCheck] = useState<CheckState>({ kind: 'idle' });
  const [claiming, setClaiming] = useState(false);
  const [claimError, setClaimError] = useState<string | null>(null);
  const checkSeq = useRef(0);

  const name = normalizeUsername(input);
  const formatError = usernameFormatError(name);
  const formatOk = isValidUsername(name);

  // Live availability: debounced, and only for a well-formed name.
  // A failed check never blocks the claim — the database's unique
  // index is the final word — it just softens the line under the
  // field to "couldn't check".
  useEffect(() => {
    if (!formatOk) {
      setCheck({ kind: 'idle' });
      return;
    }
    const seq = ++checkSeq.current;
    setCheck({ kind: 'checking' });
    const timer = setTimeout(() => {
      void (async () => {
        try {
          const available = await isUsernameAvailable(name);
          if (checkSeq.current !== seq) return;
          setCheck({ kind: available ? 'available' : 'taken' });
        } catch {
          if (checkSeq.current !== seq) return;
          setCheck({ kind: 'unverifiable' });
        }
      })();
    }, 400);
    return () => clearTimeout(timer);
  }, [name, formatOk]);

  const handleClaim = async () => {
    setClaiming(true);
    setClaimError(null);
    const result = await claimUsername(userId, name);
    setClaiming(false);
    if (result.ok) {
      onClaimed(result.username);
      return;
    }
    if (result.reason === 'taken') setCheck({ kind: 'taken' });
    setClaimError(result.message);
  };

  const helperLine = (() => {
    if (formatError) return formatError;
    if (!formatOk) return '3–20 characters: lowercase letters, numbers, underscores.';
    switch (check.kind) {
      case 'checking':
        return 'Checking…';
      case 'available':
        return `@${name} is available.`;
      case 'taken':
        return 'That @name is already taken — try another one.';
      case 'unverifiable':
        return 'Couldn’t check just now — you can still try to claim it.';
      default:
        return '3–20 characters: lowercase letters, numbers, underscores.';
    }
  })();

  const helperIsError = Boolean(formatError) || check.kind === 'taken';

  return (
    <Box data-testid="username-claim-card" sx={{ mt: 2 }}>
      <Typography variant="subtitle1" gutterBottom>
        Claim your @name
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Your @name is how other players find and friend you. Pick it well:{' '}
        <strong>once claimed, it locks to your account and can&apos;t be changed.</strong>
      </Typography>
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-start' }}>
        <TextField
          fullWidth
          size="small"
          label="Your @name"
          placeholder="e.g. maccxamillion"
          value={input}
          onChange={e => {
            // Lowercased as typed — a stored @name is always lowercase.
            setInput(e.target.value.toLowerCase());
            setClaimError(null);
          }}
          onKeyDown={e => {
            if (e.key === 'Enter' && formatOk && check.kind !== 'taken' && !claiming) {
              void handleClaim();
            }
          }}
          error={helperIsError}
          helperText={helperLine}
          inputProps={{ 'data-testid': 'username-claim-input', maxLength: 24 }}
        />
        <Button
          variant="contained"
          size="small"
          disabled={!formatOk || check.kind === 'taken' || claiming}
          onClick={() => void handleClaim()}
          data-testid="username-claim-button"
          sx={{ mt: 0.5, whiteSpace: 'nowrap' }}
        >
          {claiming ? 'Claiming…' : 'Claim @name'}
        </Button>
      </Box>
      {claimError && (
        <Typography variant="body2" color="error" sx={{ mt: 1 }} data-testid="username-claim-error">
          {claimError}
        </Typography>
      )}
    </Box>
  );
};

export default UsernameClaimCard;
