const STATE_BY_CODE = new Map(US_STATES.map(s => [s.code, s]));

export function stateName(code: string): string {
  return STATE_BY_CODE.get(code.toUpperCase())?.name ?? code;
}

export function regionForState(code: string): VenueRegion | null {
  return STATE_BY_CODE.get(code.toUpperCase())?.region ?? null;
}

export function statesInRegion(region: VenueRegion): UsState[] {
  return US_STATES.filter(s => s.region === region).sort((a, b) => a.name.localeCompare(b.name));
}

// A row of public.venue_applications.
export interface VenueApplicationRow {
  id: string;
  ref: string;
  venue_name: string;
  venue_type: string;
  city: string;
  state: string;
  region: string;
  area: string | null;
  contact_name: string;
  email: string;
  phone: string | null;
  social: string | null;
  best_night: string | null;
  perk_idea: string | null;
  glow_theme: string | null;
  notes: string | null;
  status: VenueStatus;
  created_at: string;
  updated_at: string;
}

export interface VenueApplicationInput {
  ref: string;
  venueName: string;
  venueType: string;
  city: string;
  state: string;
  contactName: string;
  email: string;
  phone: string;
  social: string;
  bestNight: string;
  perkIdea: string;
  glowTheme: string;
  notes: string;
}

// PostgREST's "table not in the schema cache" signature — how a
// not-yet-run migration shows up from the client's side.
export function isMissingTableError(error: { code?: string; message?: string } | null): boolean {
  if (!error) return false;
  if (error.code === 'PGRST205') return true;
  const m = (error.message ?? '').toLowerCase();
  return m.includes('could not find the table') || m.includes('does not exist');
}

export type VenueBackendState = 'live' | 'missing' | 'unknown';

/** Does the venue_applications table exist yet? */
export async function probeVenueBackend(): Promise<VenueBackendState> {
  const { error } = await supabase
    .from('venue_applications')
    .select('id', { count: 'exact', head: true });
  if (!error) return 'live';
  return isMissingTableError(error) ? 'missing' : 'unknown';
}

export type SubmitResult =
  { kind: 'saved' } | { kind: 'not_configured' } | { kind: 'failed'; message: string };

/** Write one application for real. Never pretends: see SubmitResult. */
export async function submitVenueApplication(input: VenueApplicationInput): Promise<SubmitResult> {
  const region = regionForState(input.state);
  const { error } = await supabase.from('venue_applications').insert({
    ref: input.ref,
    venue_name: input.venueName.trim(),
    venue_type: input.venueType,
    city: input.city.trim(),
    state: input.state.toUpperCase(),
    region: region ?? 'West',
    // area stays null in storage: the admin drill-down derives
    // the in-state grouping at read time (utils/venueAreas.ts).
    contact_name: input.contactName.trim(),
    email: input.email.trim(),
    phone: input.phone.trim() || null,
    social: input.social.trim() || null,
    best_night: input.bestNight || null,
    perk_idea: input.perkIdea.trim() || null,
    glow_theme: input.glowTheme || null,
    notes: input.notes.trim() || null,
    status: 'applied',
  });
  if (!error) return { kind: 'saved' };
  if (isMissingTableError(error)) return { kind: 'not_configured' };
  return { kind: 'failed', message: error.message };
}

/** Owner-only read (RLS decides; non-owners get an empty list). */
export async function fetchVenueApplications(): Promise<{
  rows: VenueApplicationRow[];
  missing: boolean;
  error: string | null;
}> {
  const { data, error } = await supabase
    .from('venue_applications')
    .select('*')
    .order('created_at', { ascending: false });
  if (error) {
    return { rows: [], missing: isMissingTableError(error), error: error.message };
  }
  return { rows: (data ?? []) as VenueApplicationRow[], missing: false, error: null };
}

/** Owner-only status write. Confirms the row actually changed —
 *  an RLS-blocked update returns no error but also no row. */
export async function setVenueStatus(
  id: string,
  status: VenueStatus
): Promise<{ row: VenueApplicationRow | null; error: string | null }> {
  const { data, error } = await supabase
    .from('venue_applications')
    .update({ status })
    .eq('id', id)
    .select();
  if (error) return { row: null, error: error.message };
  const row = (data ?? [])[0] as VenueApplicationRow | undefined;
  if (!row) return { row: null, error: 'That change did not go through.' };
  return { row, error: null };
}
