// WorthTheTripFeed — the citywide feed a Recognized partner's
// payment buys into (Round 29, sim §14), on Home under the
// nearby list.
//
// Normal suggestions reach about 3 miles from where the player
// is playing; Recognized partners are suggested from about 12
// miles / citywide, and this feed is where that wider ring
// lives. It is labelled as what it is — paid placements, in the
// heading's own words — and it carries the player's mute for
// promoted pop-up suggestions (§14: muting stops the pop-ups
// entirely and never affects normal nearby discovery; the feed
// itself stays, it is a list the player chose to open).
//
// Distances are measured from the suggestion anchor (the
// checked-in venue, else home base) with the demo's stand-in
// geography — see utils/venuePerks.ts.
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Button, Chip, FormControlLabel, Paper, Switch, Typography } from '@mui/material';
import { buzzForVenue } from '../data/venueBuzz';
import { useVenue } from '../contexts/VenueContext';
import { RecognizedChip } from './PlaceTags';
import {
  distanceMi,
  getPool,
  promotedMuted,
  setPromotedMuted,
  suggestionAnchor,
  useVenuePerksVersion,
  worthTheTripVenues,
} from '../utils/venuePerks';

export default function WorthTheTripFeed() {
  const navigate = useNavigate();
  const { checkedInVenueId } = useVenue();
  useVenuePerksVersion();
  const anchor = suggestionAnchor(checkedInVenueId);
  const venues = worthTheTripVenues(anchor);
  const muted = promotedMuted();

  return (
    <Box data-testid="worth-the-trip-feed" sx={{ mb: 3 }}>
      <Typography variant="h5" gutterBottom>
        Worth the Trip
        <Chip label="DEMO" size="small" sx={{ ml: 1, verticalAlign: 'middle' }} />
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Recognized venues from across the city — paid placements, labelled as what they are. A
        normal listing is suggested within about 3 miles; Recognized partners reach about 12.
      </Typography>
      <FormControlLabel
        control={
          <Switch
            checked={muted}
            onChange={e => setPromotedMuted(e.target.checked)}
            data-testid="mute-promoted-switch"
          />
        }
        label="Mute promoted suggestions"
        sx={{ mb: 1.5 }}
      />
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
        {venues.length === 0 && (
          <Typography variant="body2" color="text.secondary">
            No Recognized venues are in the wider ring from {anchor.label} right now.
          </Typography>
        )}
        {venues.map(v => {
          const buzz = buzzForVenue(v.id);
          const pool = getPool(v.id);
          return (
            <Paper key={v.id} data-testid="worth-trip-card" data-venue-id={v.id} sx={{ p: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Typography variant="subtitle1">{v.name}</Typography>
                <RecognizedChip />
              </Box>
              <Typography variant="body2" color="text.secondary">
                {v.area} · {distanceMi(anchor, v).toFixed(1)} miles away · {v.tagline}
              </Typography>
              {buzz?.event && (
                <Typography variant="body2">
                  🎉 {buzz.event.name} — {buzz.event.when}
                </Typography>
              )}
              <Typography variant="body2">
                🎁 {pool.creditsLeft} sponsored $5 credits available tonight
              </Typography>
              <Button size="small" onClick={() => navigate('/map')} sx={{ mt: 0.5 }}>
                Map
              </Button>
            </Paper>
          );
        })}
      </Box>
    </Box>
  );
}
