// ADMIN PORTAL (Round 37-V2, Eddie 2026-11-20 ~18:02 PT): "add an
// administrator portal at the bottom of the page and I could just
// go in there and just give me a special password." The R37-V door
// lived inside the Owner Mode section and Eddie had to hunt for
// it; this is the findable entrance: a portal at the bottom of
// Profile, opened by a password Eddie sets himself on the device.
//
// WHAT THE PASSWORD IS — AND ISN'T: it guards this door, on this
// device, only. What is stored is a SHA-256 hash (never the
// password, never anything reversible) in localStorage under
// ADMIN_PORTAL_KEY. The venue DATA behind the door stays locked
// exactly where it always was: Supabase RLS opens application
// records only to a signed-in owner email. A guessed door password
// on a stranger's phone opens an empty, honest window — no data.
//
// SESSION: a correct password sets a sessionStorage flag; the
// portal then stays unlocked for the browser session (no re-asking
// on every visit). The Lock control in the admin window clears the
// flag (not the stored hash), and the reset path on the prompt
// clears the hash so a new password can be set on this device.
import { useEffect, useState } from 'react';

export const ADMIN_PORTAL_KEY = 'glacer-admin-portal';
export const ADMIN_PORTAL_SESSION_KEY = 'glacer-admin-portal-unlocked';
const ADMIN_PORTAL_EVENT = 'glacer-admin-portal-session';

// ---------------------------------------------------------------------
// SHA-256. crypto.subtle where the platform offers it (https /
// localhost — everywhere this app runs); a plain-JS implementation
// underneath so the stored value is a real SHA-256 digest in every
// environment. Both paths are verified against the same vectors.
// ---------------------------------------------------------------------

const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function sha256HexSync(ascii: string): string {
  // Input is encoded as UTF-8 first so non-ASCII passwords hash the
  // same here as they do through crypto.subtle.
  const bytes: number[] = [];
  for (let i = 0; i < ascii.length; i++) {
    const code = ascii.charCodeAt(i);
    if (code < 0x80) bytes.push(code);
    else if (code < 0x800) bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    else if (code >= 0xd800 && code <= 0xdbff && i + 1 < ascii.length) {
      const cp = 0x10000 + ((code - 0xd800) << 10) + (ascii.charCodeAt(++i) - 0xdc00);
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  // 64-bit big-endian bit length (high word is 0 at these sizes).
  bytes.push(0, 0, 0, 0);
  bytes.push((bitLen >>> 24) & 0xff, (bitLen >>> 16) & 0xff, (bitLen >>> 8) & 0xff, bitLen & 0xff);

  let h0 = 0x6a09e667,
    h1 = 0xbb67ae85,
    h2 = 0x3c6ef372,
    h3 = 0xa54ff53a;
  let h4 = 0x510e527f,
    h5 = 0x9b05688c,
    h6 = 0x1f83d9ab,
    h7 = 0x5be0cd19;
  const w = new Array<number>(64);
  const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));

  for (let block = 0; block < bytes.length; block += 64) {
    for (let t = 0; t < 16; t++) {
      const j = block + t * 4;
      w[t] = (bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let a = h0,
      b = h1,
      c = h2,
      d = h3,
      e = h4,
      f = h5,
      g = h6,
      h = h7;
    for (let t = 0; t < 64; t++) {
      const s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + s1 + ch + SHA256_K[t] + w[t]) | 0;
      const s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (s0 + maj) | 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) | 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) | 0;
    }
    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
    h5 = (h5 + f) | 0;
    h6 = (h6 + g) | 0;
    h7 = (h7 + h) | 0;
  }
  const hex = (n: number) => (n >>> 0).toString(16).padStart(8, '0');
  return [h0, h1, h2, h3, h4, h5, h6, h7].map(hex).join('');
}

export async function sha256Hex(text: string): Promise<string> {
  try {
    if (typeof crypto !== 'undefined' && crypto.subtle?.digest) {
      const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
      return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch {
    // fall through to the plain-JS digest
  }
  return sha256HexSync(text);
}

// ---------------------------------------------------------------------
// Stored hash (localStorage — this device only)
// ---------------------------------------------------------------------

export function readAdminPasswordHash(): string | null {
  try {
    const v = localStorage.getItem(ADMIN_PORTAL_KEY);
    return v && /^[0-9a-f]{64}$/.test(v) ? v : null;
  } catch {
    return null;
  }
}

export function hasAdminPassword(): boolean {
  return readAdminPasswordHash() !== null;
}

/** Store ONLY the SHA-256 hash of the password Eddie just set. */
export async function setAdminPassword(password: string): Promise<void> {
  const hash = await sha256Hex(password);
  try {
    localStorage.setItem(ADMIN_PORTAL_KEY, hash);
  } catch {
    // storage unavailable — the set simply doesn't persist
  }
}

export async function checkAdminPassword(password: string): Promise<boolean> {
  const stored = readAdminPasswordHash();
  if (!stored) return false;
  return (await sha256Hex(password)) === stored;
}

/** Reset path: forget the password on this device (hash + session). */
export function clearAdminPassword(): void {
  try {
    localStorage.removeItem(ADMIN_PORTAL_KEY);
  } catch {
    // nothing to clear
  }
  lockPortal();
}

// ---------------------------------------------------------------------
// Session unlock (sessionStorage — this browser session only)
// ---------------------------------------------------------------------

export function isPortalUnlocked(): boolean {
  try {
    return sessionStorage.getItem(ADMIN_PORTAL_SESSION_KEY) === '1';
  } catch {
    return false;
  }
}

export function unlockPortal(): void {
  try {
    sessionStorage.setItem(ADMIN_PORTAL_SESSION_KEY, '1');
  } catch {
    // session storage unavailable — the unlock lasts this render
  }
  window.dispatchEvent(new Event(ADMIN_PORTAL_EVENT));
}

/** Lock control: clears the session unlock, never the stored hash. */
export function lockPortal(): void {
  try {
    sessionStorage.removeItem(ADMIN_PORTAL_SESSION_KEY);
  } catch {
    // nothing to clear
  }
  window.dispatchEvent(new Event(ADMIN_PORTAL_EVENT));
}

/** Reactive session-unlock check (mirrors useOwnerMode's pattern). */
export function usePortalUnlocked(): boolean {
  const [unlocked, setUnlocked] = useState<boolean>(isPortalUnlocked);
  useEffect(() => {
    const sync = () => setUnlocked(isPortalUnlocked());
    window.addEventListener(ADMIN_PORTAL_EVENT, sync);
    window.addEventListener('storage', sync);
    return () => {
      window.removeEventListener(ADMIN_PORTAL_EVENT, sync);
      window.removeEventListener('storage', sync);
    };
  }, []);
  return unlocked;
}
